import React, { useEffect, useRef, useState } from 'react';
import { View, Text, FlatList, TouchableOpacity, Image, Dimensions, StyleSheet, Animated, Alert } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { VideoView, useVideoPlayer } from 'expo-video';
import { useFocusEffect } from 'expo-router';
const useIsFocused = () => { const [f, sF] = React.useState(true); useFocusEffect(React.useCallback(() => { sF(true); return () => sF(false); }, [])); return f; };
import { useRouter } from 'expo-router';
import { collection, query, where, orderBy, onSnapshot, doc, updateDoc, arrayUnion, arrayRemove, increment, addDoc, setDoc, serverTimestamp } from 'firebase/firestore';
import { auth, db } from '../config';
import { BRAND } from '../constants/theme';
import { CommentModal } from '../constants/CommentModal';
import { ShareModal } from '../constants/ShareModal';
import { StoryViewerModal } from '../constants/StoryViewerModal';
import { ReelModals } from '../constants/ReelModals';

const { height: H } = Dimensions.get('window');

function ReelItem({ item, active, me, hasStory, onOpenStory, onTapAvatar, onLike, onComment, onRepost, onOpenThought, onShare, onSave, onMenu, captions, fullscreen }: any) {
  const uid = auth.currentUser?.uid || '';
    const player = useVideoPlayer(item.mediaUrl, (p) => { p.loop = true; });
      const [tapPos, setTapPos] = useState<{ x: number; y: number } | null>(null);
        const scale = useRef(new Animated.Value(0)).current;
          const lastTap = useRef(0);

            useEffect(() => {
                if (active) { player.play(); updateDoc(doc(db, 'posts', item.id), { views: increment(1) }).catch(() => {}); }
                    else player.pause();
                      }, [active]);

                        const handleTap = (e: any) => {
                            const now = Date.now();
                                if (now - lastTap.current < 300) {
                                      setTapPos({ x: e.nativeEvent.locationX, y: e.nativeEvent.locationY });
                                            scale.setValue(0.3);
                                                  Animated.sequence([
                                                          Animated.spring(scale, { toValue: 1.2, useNativeDriver: true }),
                                                                  Animated.timing(scale, { toValue: 0, duration: 250, useNativeDriver: true }),
                                                                        ]).start(() => setTapPos(null));
                                                                              if (!(item.likes || []).includes(uid)) onLike(item);
                                                                                  }
                                                                                      lastTap.current = now;
                                                                                        };

                                                                                          const liked = (item.likes || []).includes(uid);
                                                                                            const reposted = (item.reposts || []).includes(uid);
                                                                                              const saved = (me?.savedPosts || []).includes(item.id);
                                                                                                const following = (me?.following || []).includes(item.uid);

                                                                                                  return (
                                                                                                      <TouchableOpacity activeOpacity={1} onPress={handleTap} style={styles.reel}>
                                                                                                            <VideoView player={player} style={StyleSheet.absoluteFillObject} contentFit="cover" nativeControls={false} />
                                                                                                                  {tapPos && (
                                                                                                                          <Animated.View style={[styles.tapHeart, { left: tapPos.x - 42, top: tapPos.y - 42, transform: [{ scale }] }]} pointerEvents="none">
                                                                                                                                    <Ionicons name="heart" size={84} color="#F97316" />
                                                                                                                                            </Animated.View>
                                                                                                                                                  )}
                                                                                                                                                        {!fullscreen && (
                                                                                                                                                                <>
                                                                                                                                                                          <View style={styles.rightCol}>
                                                                                                                                                                                      <TouchableOpacity onPress={() => onLike(item)} style={styles.act}><Ionicons name={liked ? 'heart' : 'heart-outline'} size={30} color={liked ? '#EF4444' : '#fff'} /><Text style={styles.cnt}>{item.likes?.length || 0}</Text></TouchableOpacity>
                                                                                                                                                                                                  <TouchableOpacity onPress={() => onComment(item.id)} style={styles.act}><Ionicons name="chatbubble-outline" size={28} color="#fff" /><Text style={styles.cnt}>Chat</Text></TouchableOpacity>
                                                                                                                                                                                                              <TouchableOpacity onPress={() => onRepost(item)} style={styles.act}><Ionicons name="repeat" size={29} color={reposted ? BRAND : '#fff'} /><Text style={styles.cnt}>{item.reposts?.length || 0}</Text></TouchableOpacity>
                                                                                                                                                                                                                          <TouchableOpacity onPress={() => onShare(item)} style={styles.act}><Ionicons name="paper-plane-outline" size={27} color="#fff" /></TouchableOpacity>
                                                                                                                                                                                                                                      <TouchableOpacity onPress={() => onSave(item.id)} style={styles.act}><Ionicons name={saved ? 'bookmark' : 'bookmark-outline'} size={27} color={saved ? BRAND : '#fff'} /></TouchableOpacity>
                                                                                                                                                                                                                                                  <TouchableOpacity onPress={() => onMenu(item)} style={styles.act}><Ionicons name="reorder-two-outline" size={28} color="#fff" /></TouchableOpacity>
                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                      <View style={styles.bottomLeft}>
                                                                                                                                                                                                                                                                                  {reposted && (
                                                                                                                                                                                                                                                                                                <TouchableOpacity style={styles.repostWrap} onPress={() => onOpenThought(item)}>
                                                                                                                                                                                                                                                                                                                <View style={styles.thoughtTag}><Text style={{ fontSize: 11, fontWeight: '700', color: '#111827' }}>Add a thought...</Text></View>
                                                                                                                                                                                                                                                                                                                                <Image source={{ uri: me?.avatar || item.userAvatar || 'https://ui-avatars.com/api/?name=U' }} style={styles.repostAv} />
                                                                                                                                                                                                                                                                                                                                              </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                          )}
                                                                                                                                                                                                                                                                                                                                                                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}>
                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity onPress={() => (hasStory ? onOpenStory(item.uid) : onTapAvatar(item.uid))} style={[styles.avRing, hasStory && { borderColor: BRAND, borderWidth: 2.5 }]}>
                                                                                                                                                                                                                                                                                                                                                                                                    <Image source={{ uri: item.userAvatar || 'https://ui-avatars.com/api/?name=' + (item.username || 'U') }} style={styles.av} />
                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                <Text style={styles.user}>@{item.username}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                              {item.uid !== uid && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity style={styles.fBtn} onPress={() => updateDoc(doc(db, 'users', uid), { following: following ? arrayRemove(item.uid) : arrayUnion(item.uid) })}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Text style={{ color: '#fff', fontSize: 12, fontWeight: '700' }}>{following ? 'Following' : 'Follow'}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {captions && !!item.caption && <Text style={{ color: '#fff', marginTop: 6 }} numberOfLines={2}>{item.caption}</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    export default function ReelsScreen() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const router = useRouter();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const focused = useIsFocused();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const uid = auth.currentUser?.uid || '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const [reels, setReels] = useState<any[]>([]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const [stories, setStories] = useState<any[]>([]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const [me, setMe] = useState<any>(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const [idx, setIdx] = useState(0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const [commentId, setCommentId] = useState<string | null>(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const [sharePost, setSharePost] = useState<any | null>(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const [storyIdx, setStoryIdx] = useState<number | null>(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const [thoughtReel, setThoughtReel] = useState<any | null>(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const [menuReel, setMenuReel] = useState<any | null>(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const [repostBanner, setRepostBanner] = useState<string | null>(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const [playbackOpen, setPlaybackOpen] = useState(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const [fullscreen, setFullscreen] = useState(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const [autoScroll, setAutoScroll] = useState(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const [captions, setCaptions] = useState(true);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        useEffect(() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const u1 = onSnapshot(query(collection(db, 'posts'), where('mediaType', '==', 'video'), orderBy('createdAt', 'desc')), (s) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setReels(s.docs.map((d) => ({ id: d.id, ...d.data() })));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const u2 = onSnapshot(query(collection(db, 'stories'), orderBy('createdAt', 'desc')), (s) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setStories(s.docs.map((d) => ({ id: d.id, ...d.data() })).filter((st: any) => !st.expiresAt || st.expiresAt > Date.now()));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const u3 = uid ? onSnapshot(doc(db, 'users', uid), (s) => { if (s.exists()) setMe(s.data()); }) : () => {};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return () => { u1(); u2(); u3(); };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }, [uid]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const visible = reels.filter((r) => !(me?.hiddenPosts || []).includes(r.id) && !(me?.blockedUsers || []).includes(r.uid));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const toggleRepost = async (item: any) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!uid) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const has = (item.reposts || []).includes(uid);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await updateDoc(doc(db, 'posts', item.id), { reposts: has ? arrayRemove(uid) : arrayUnion(uid) });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!has) { setRepostBanner(item.id); setTimeout(() => setRepostBanner(null), 3500); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const saveThought = async (item: any, txt: string) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!uid || !item || !txt.trim()) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const chatId = [uid, item.uid].sort().join('_');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  await setDoc(doc(db, 'conversations', chatId), { participants: [uid, item.uid], updatedAt: serverTimestamp() }, { merge: true });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await addDoc(collection(db, 'conversations', chatId, 'messages'), {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            senderUid: uid, text: `Reposted your reel: ${txt.trim()}`, mediaUrl: item.mediaUrl, mediaType: 'video', read: false, createdAt: serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Alert.alert('Sent', 'Thought sent to creator DM!');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={{ flex: 1, backgroundColor: '#000' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <FlatList
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          data={visible} pagingEnabled showsVerticalScrollIndicator={false} keyExtractor={(i) => i.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  windowSize={3} maxToRenderPerBatch={2} removeClippedSubviews
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onMomentumScrollEnd={(e) => setIdx(Math.round(e.nativeEvent.contentOffset.y / (H - 56)))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  renderItem={({ item, index }) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <ReelItem
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        item={item} active={focused && index === idx} me={me} fullscreen={fullscreen} captions={captions}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    hasStory={stories.some((s) => s.uid === item.uid)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onOpenStory={(creatorUid: string) => setStoryIdx(stories.findIndex((s) => s.uid === creatorUid))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onTapAvatar={(u: string) => router.push(`/user/${u}` as any)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onLike={(it: any) => uid && updateDoc(doc(db, 'posts', it.id), { likes: (it.likes || []).includes(uid) ? arrayRemove(uid) : arrayUnion(uid) })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onComment={setCommentId} onRepost={toggleRepost} onOpenThought={setThoughtReel}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onShare={setSharePost} onMenu={setMenuReel}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onSave={(id: string) => uid && updateDoc(doc(db, 'users', uid), { savedPosts: (me?.savedPosts || []).includes(id) ? arrayRemove(id) : arrayUnion(id) })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {repostBanner && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={styles.toast}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={{ color: '#fff', fontWeight: '700' }}>Reposted</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity onPress={() => { toggleRepost({ id: repostBanner, reposts: [uid] }); setRepostBanner(null); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={{ color: '#60A5FA', fontWeight: '700' }}>Undo</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <CommentModal postId={commentId} onClose={() => setCommentId(null)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <ShareModal post={sharePost} onClose={() => setSharePost(null)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <StoryViewerModal stories={stories} activeIdx={storyIdx} setActiveIdx={setStoryIdx} uid={uid} me={me} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <ReelModals
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          thoughtReel={thoughtReel} setThoughtReel={setThoughtReel} me={me} onSaveThought={saveThought}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onUndoRepost={(id: string) => id && updateDoc(doc(db, 'posts', id), { reposts: arrayRemove(uid) })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          menuReel={menuReel} setMenuReel={setMenuReel}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onNotInterested={(id: string) => id && uid && updateDoc(doc(db, 'users', uid), { hiddenPosts: arrayUnion(id) })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onReport={(id: string) => id && addDoc(collection(db, 'reports'), { postId: id, type: 'reel', status: 'pending', reportedBy: uid, createdAt: serverTimestamp() })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  playbackOpen={playbackOpen} setPlaybackOpen={setPlaybackOpen} fullscreen={fullscreen} setFullscreen={setFullscreen}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          autoScroll={autoScroll} setAutoScroll={setAutoScroll} captions={captions} setCaptions={setCaptions}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const styles = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        reel: { height: H - 56, backgroundColor: '#000', justifyContent: 'flex-end' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          tapHeart: { position: 'absolute', zIndex: 30 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            rightCol: { position: 'absolute', right: 12, bottom: 30, alignItems: 'center', gap: 16, zIndex: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              act: { alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cnt: { color: '#fff', fontSize: 12, fontWeight: '700', marginTop: 2 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  bottomLeft: { padding: 16, paddingRight: 74, zIndex: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    repostWrap: { marginBottom: 10, alignSelf: 'flex-start' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      thoughtTag: { backgroundColor: '#fff', paddingHorizontal: 10, paddingVertical: 4, borderRadius: 12, marginBottom: 4 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        repostAv: { width: 34, height: 34, borderRadius: 17, borderWidth: 2, borderColor: BRAND },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          avRing: { width: 40, height: 40, borderRadius: 20, padding: 2, justifyContent: 'center', alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            av: { width: 34, height: 34, borderRadius: 17 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              user: { color: '#fff', fontWeight: '800', fontSize: 15 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fBtn: { borderWidth: 1, borderColor: '#fff', paddingHorizontal: 10, paddingVertical: 3, borderRadius: 8 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  toast: { position: 'absolute', bottom: 16, left: 16, right: 16, backgroundColor: '#27272A', padding: 14, borderRadius: 12, flexDirection: 'row', justifyContent: 'space-between', zIndex: 40 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  